import{_ as e,o as i,c as l,a5 as t}from"./chunks/framework.DJo0M80U.js";const p=JSON.parse('{"title":"Java概述","description":"","frontmatter":{"title":"Java概述","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","Java基础","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第一部分：语言基础/01-基础语法/Java概述.md","filePath":"posts/java快速入门/第一部分：语言基础/01-基础语法/Java概述.md"}'),v={name:"posts/java快速入门/第一部分：语言基础/01-基础语法/Java概述.md"};function r(o,a,s,n,J,d){return i(),l("div",null,[...a[0]||(a[0]=[t('<div><p><strong>什么是 Java 语言</strong></p><p>Java 语言是美国 Sun 公司（Stanford University Network）在 1995 年推出的高级编程语言。所谓编程语言，是计算机的语言，人们可以使用编程语言对计算机下达命令，让计算机完成人们需要的功能。</p><h2 id="java-语言发展历史" tabindex="-1">Java 语言发展历史 <a class="header-anchor" href="#java-语言发展历史" aria-label="Permalink to &quot;Java 语言发展历史&quot;">​</a></h2><ul><li>1995 年 Sun 公司发布 Java 1.0 版本</li><li>1997 年发布 Java 1.1 版本</li><li>1998 年发布 Java 1.2 版本</li><li>2000 年发布 Java 1.3 版本</li><li>2002 年发布 Java 1.4 版本</li><li>2004 年发布 Java 1.5 版本</li><li>2006 年发布 Java 1.6 版本</li><li>2009 年 Oracle 甲骨文公司收购 Sun 公司，并于 2011 发布 Java 1.7 版本</li><li>2014 年发布 Java 1.8 版本</li><li>2017 年发布 Java 9.0 版本</li></ul><h2 id="java-语言能做什么" tabindex="-1">Java 语言能做什么 <a class="header-anchor" href="#java-语言能做什么" aria-label="Permalink to &quot;Java 语言能做什么&quot;">​</a></h2><p>Java 语言主要应用在互联网程序的开发领域。常见的互联网程序比如天猫、京东、物流系统、网银系统等，以及服务器后台处理大数据的存储、查询、数据挖掘等也有很多应用。</p><h2 id="java-主要在以下方面比-c-更容易" tabindex="-1">Java 主要在以下方面比 C++ 更容易 <a class="header-anchor" href="#java-主要在以下方面比-c-更容易" aria-label="Permalink to &quot;Java 主要在以下方面比 C++ 更容易&quot;">​</a></h2><ul><li>Java 自动负责内存的分配和释放</li><li>Java 没有指针（对经验丰富的程序员来说，指针是强大特性，但也容易误用并带来安全隐患）</li><li>Java 只具备面向对象编程中的单继承</li><li>Java 之所以安全，两个关键因素是：没有指针，且能自动管理内存</li></ul><h2 id="程序结构-由大到小" tabindex="-1">程序结构（由大到小） <a class="header-anchor" href="#程序结构-由大到小" aria-label="Permalink to &quot;程序结构（由大到小）&quot;">​</a></h2><p>Java 程序是由类和对象组成的，而对象和类又是由方法和变量组成的；方法是由语句和表达式组成的，表达式又由运算符组成。</p></div>',1)])])}const _=e(v,[["render",r]]);export{p as __pageData,_ as default};
